import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import org.springframework.stereotype.Service;

@Service
public class OrderProcessingService {

    private final Counter orderCounter;
    private final Timer processingTimer;

    public OrderProcessingService(MeterRegistry registry) {
        this.orderCounter = Counter.builder("app.orders.processed")
            .description("Total number of successfully processed orders")
            .tag("module", "checkout")
            .register(registry);

        this.processingTimer = Timer.builder("app.orders.latency")
            .description(
                "Time taken to process an order"
            )
            .register(registry);
    }

    public void processOrder(String orderId) {
        processingTimer.record(() -> {
            // Simulate core business logic execution
            try {
                Thread.sleep(45);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            orderCounter.increment();
        });
    }
}
